#!/usr/bin/env python3
"""Atomic HTTP/3-to-HTTP/1.1 bridge: validation, atomicity, duplicates, framing."""
import json
import sys
import ipaddress


class Reject(Exception):
    pass


# ---------------------------------------------------------------------------
# Octet-level validators
# ---------------------------------------------------------------------------
NAME_PUNCT = frozenset(b"!#$%&'*+-.^_`|~")
PATH_PUNCT = frozenset(b"-._~!$&'()*+,;=:@/?")
HEXDIG = frozenset(b"0123456789abcdefABCDEF")
ALLOWED_METHODS = frozenset(
    [b'GET', b'HEAD', b'POST', b'PUT', b'PATCH', b'DELETE', b'OPTIONS'])
PROHIBITED = frozenset([
    b'connection', b'proxy-connection', b'keep-alive', b'transfer-encoding',
    b'upgrade', b'http2-settings', b'trailer'])
REPEAT_ALLOWED = frozenset([
    b'accept', b'accept-encoding', b'cache-control', b'if-match',
    b'if-none-match', b'pragma', b'vary'])


def _edge(b):
    return (0x21 <= b <= 0x7E) or (0x80 <= b <= 0xFF)


def valid_value(v):
    n = len(v)
    if n == 0:
        return True
    if not _edge(v[0]) or not _edge(v[-1]):
        return False
    for b in v[1:-1]:
        if b == 0x09 or b == 0x20 or (0x21 <= b <= 0x7E) or (0x80 <= b <= 0xFF):
            continue
        return False
    return True


def valid_regular_name(n):
    if not n:
        return False
    for b in n:
        if 0x61 <= b <= 0x7A or 0x30 <= b <= 0x39 or b in NAME_PUNCT:
            continue
        return False
    return True


def valid_path(path, method_b):
    if path == b'*':
        return method_b == b'OPTIONS'
    if not path or path[0:1] != b'/':
        return False
    if path[0:2] == b'//':
        return False
    i = 0
    n = len(path)
    while i < n:
        b = path[i]
        if (0x41 <= b <= 0x5A) or (0x61 <= b <= 0x7A) or (0x30 <= b <= 0x39) or (b in PATH_PUNCT):
            i += 1
            continue
        if b == 0x25:  # '%'
            if i + 2 < n and path[i + 1] in HEXDIG and path[i + 2] in HEXDIG:
                i += 3
                continue
            return False
        return False
    return True


def _is_alnum(b):
    return (0x41 <= b <= 0x5A) or (0x61 <= b <= 0x7A) or (0x30 <= b <= 0x39)


def validate_port(p):
    if p is None:
        return None
    if not (1 <= len(p) <= 5):
        return None
    for b in p:
        if not (0x30 <= b <= 0x39):
            return None
    val = int(p)
    if val < 1 or val > 65535:
        return None
    return val


def validate_host(h):
    if not h:
        return None
    for b in h:
        if b >= 0x80:
            return None
    labels = h.split(b'.')
    all_digits = all(len(l) > 0 and l.isdigit() for l in labels)
    if len(labels) == 4 and all_digits:
        comps = []
        for l in labels:
            if len(l) == 0:
                return None
            if len(l) > 1 and l[0:1] == b'0':
                return None
            if not l.isdigit():
                return None
            v = int(l)
            if v > 255:
                return None
            comps.append(str(v))
        return '.'.join(comps).encode('ascii')
    # DNS-style
    if len(h) < 1 or len(h) > 253:
        return None
    for l in labels:
        if len(l) < 1 or len(l) > 63:
            return None
        if not (_is_alnum(l[0]) and _is_alnum(l[-1])):
            return None
        for b in l:
            if not (_is_alnum(b) or b == 0x2D):
                return None
    return h.lower()


def parse_authority(a, scheme):
    """Return canonical authority string, or None."""
    if not a:
        return None
    if a[0:1] == b'[':
        idx = a.find(b']')
        if idx < 0:
            return None
        inner = a[1:idx]
        rest = a[idx + 1:]
        if b'%' in inner:
            return None
        try:
            addr = ipaddress.IPv6Address(inner.decode('ascii'))
        except Exception:
            return None
        host = b'[' + addr.compressed.encode('ascii') + b']'
        if rest:
            if rest[0:1] != b':':
                return None
            port = rest[1:]
            has_port = True
        else:
            port = None
            has_port = False
    else:
        if a.count(b':') > 1:
            return None
        if b':' in a:
            host_part, port = a.split(b':', 1)
            has_port = True
        else:
            host_part = a
            port = None
            has_port = False
        hv = validate_host(host_part)
        if hv is None:
            return None
        host = hv
    port_int = None
    if has_port:
        port_int = validate_port(port)
        if port_int is None:
            return None
    default = 80 if scheme == 'http' else 443
    host_str = host.decode('latin-1')
    if (not has_port) or port_int == default:
        return host_str
    return host_str + ':' + str(port_int)


# ---------------------------------------------------------------------------
# Serialization
# ---------------------------------------------------------------------------
def build_request(method_b, path_b, canon_auth, regular, content, trailing, has_trailing):
    out = bytearray()
    out += method_b + b' ' + path_b + b' HTTP/1.1\r\n'
    out += b'host: ' + canon_auth.encode('ascii') + b'\r\n'
    cookies = [v for (n, v) in regular if n == b'cookie']
    cookie_emitted = False
    for name, value in regular:
        if name in (b'host', b'content-length', b'te'):
            continue
        if name == b'cookie':
            if not cookie_emitted:
                out += b'cookie: ' + b'; '.join(cookies) + b'\r\n'
                cookie_emitted = True
            continue
        out += name + b': ' + value + b'\r\n'

    if not has_trailing:
        out += b'content-length: ' + str(len(content)).encode('ascii') + b'\r\n'
        out += b'\r\n'
        out += content
    else:
        out += b'transfer-encoding: chunked\r\n'
        if trailing:
            names = []
            seen = set()
            for n, v in trailing:
                if n not in seen:
                    seen.add(n)
                    names.append(n)
            out += b'trailer: ' + b', '.join(names) + b'\r\n'
        out += b'\r\n'
        if content:
            out += format(len(content), 'x').encode('ascii') + b'\r\n'
            out += content + b'\r\n'
        out += b'0\r\n'
        for n, v in trailing:
            out += n + b': ' + v + b'\r\n'
        out += b'\r\n'
    return bytes(out)


# ---------------------------------------------------------------------------
# Per-stream validation
# ---------------------------------------------------------------------------
def to_pairs(raw_pairs):
    return [(p[0].encode('latin-1'), p[1].encode('latin-1')) for p in raw_pairs]


def validate_stream(items, routes):
    if not items or items[0][0] != 'h':
        raise Reject

    initial_raw = items[0][1]
    rest = items[1:]
    hpos = [i for i, it in enumerate(rest) if it[0] == 'h']
    if len(hpos) > 1:
        raise Reject
    if len(hpos) == 1:
        p = hpos[0]
        if p != len(rest) - 1:
            raise Reject
        trailing_raw = rest[p][1]
        data_items = rest[:p]
        has_trailing = True
    else:
        trailing_raw = None
        data_items = rest
        has_trailing = False

    content = bytearray()
    for it in data_items:
        if it[0] != 'd':
            raise Reject
        content += it[1]
    if len(content) > 65536:
        raise Reject

    initial = to_pairs(initial_raw)
    if sum(len(n) + len(v) + 32 for n, v in initial) > 8192:
        raise Reject
    for n, v in initial:
        if not valid_value(v):
            raise Reject

    pseudo = {}
    regular = []
    seen_regular = False
    for name, value in initial:
        if name[:1] == b':':
            if seen_regular:
                raise Reject
            if name not in (b':method', b':scheme', b':authority', b':path'):
                raise Reject
            if name in pseudo:
                raise Reject
            pseudo[name] = value
        else:
            seen_regular = True
            if not valid_regular_name(name):
                raise Reject
            regular.append((name, value))

    for req in (b':method', b':scheme', b':path'):
        if req not in pseudo:
            raise Reject
    method_b = pseudo[b':method']
    scheme_b = pseudo[b':scheme']
    path_b = pseudo[b':path']

    if method_b not in ALLOWED_METHODS:
        raise Reject
    if scheme_b not in (b'http', b'https'):
        raise Reject
    scheme = scheme_b.decode('ascii')
    if not valid_path(path_b, method_b):
        raise Reject

    # authority / host
    auth_b = pseudo.get(b':authority')
    host_vals = [v for n, v in regular if n == b'host']
    if len(host_vals) > 1:
        raise Reject
    host_b = host_vals[0] if host_vals else None
    if auth_b is None and host_b is None:
        raise Reject
    if auth_b is not None and host_b is not None:
        if auth_b != host_b:
            raise Reject
        auth = auth_b
    elif auth_b is not None:
        auth = auth_b
    else:
        auth = host_b
    if len(auth) == 0:
        raise Reject
    canon = parse_authority(auth, scheme)
    if canon is None:
        raise Reject
    origin = routes.get(scheme + '://' + canon)
    if origin is None:
        raise Reject

    # prohibited fields
    for name, value in regular:
        if name in PROHIBITED:
            raise Reject

    # te
    te_lines = [v for n, v in regular if n == b'te']
    if len(te_lines) > 1:
        raise Reject
    if len(te_lines) == 1 and te_lines[0] != b'trailers':
        raise Reject

    # content-length
    cl_lines = [v for n, v in regular if n == b'content-length']
    if cl_lines:
        target = None
        for line in cl_lines:
            for member in line.split(b','):
                m = member.strip(b' \t')
                if len(m) == 0:
                    raise Reject
                for b in m:
                    if not (0x30 <= b <= 0x39):
                        raise Reject
                val = int(m)
                if target is None:
                    target = val
                elif val != target:
                    raise Reject
        if target != len(content):
            raise Reject

    # duplicate rules for ordinary fields
    counts = {}
    for name, value in regular:
        if name in (b'host', b'content-length', b'te', b'cookie'):
            continue
        counts[name] = counts.get(name, 0) + 1
    for name, c in counts.items():
        if c > 1:
            if name in REPEAT_ALLOWED:
                continue
            if name.startswith(b'x-list-') and len(name) > len(b'x-list-'):
                continue
            raise Reject

    # trailers
    trailing = []
    if has_trailing:
        tpairs = to_pairs(trailing_raw)
        if sum(len(n) + len(v) + 32 for n, v in tpairs) > 8192:
            raise Reject
        for name, value in tpairs:
            if not valid_value(value):
                raise Reject
            if not valid_regular_name(name):
                raise Reject
            if not name.startswith(b'x-audit-') or len(name) <= len(b'x-audit-'):
                raise Reject
            trailing.append((name, value))

    return method_b, scheme, path_b, canon, origin, regular, bytes(content), trailing, has_trailing


def record(sid, status):
    return {'sid': sid, 'status': status, 'commit_at': None, 'origin': None,
            'offset': None, 'length': 0, 'cache_key': None}


def handle_fin(sid, index, items, routes, pipelines):
    try:
        method_b, scheme, path_b, canon, origin, regular, content, trailing, has_trailing = validate_stream(items, routes)
    except Reject:
        return record(sid, 'rejected')
    raw = build_request(method_b, path_b, canon, regular, content, trailing, has_trailing)
    pipe = pipelines[origin]
    offset = len(pipe)
    pipe.extend(raw)
    return {'sid': sid, 'status': 'forwarded', 'commit_at': index, 'origin': origin,
            'offset': offset, 'length': len(raw),
            'cache_key': [method_b.decode('latin-1'), scheme, canon, path_b.decode('latin-1')]}


def bridge(scenario):
    routes = scenario['routes']
    pipelines = {label: bytearray() for label in routes.values()}
    states = {}
    for index, event in enumerate(scenario['events']):
        sid = event['sid']
        st = states.get(sid)
        if st is None:
            st = {'items': [], 'result': None}
            states[sid] = st
        if st['result'] is not None:
            continue
        kind = event['type']
        if kind == 'headers':
            st['items'].append(('h', event['fields']))
        elif kind == 'data':
            st['items'].append(('d', bytes.fromhex(event['hex'])))
        elif kind == 'unknown':
            pass
        elif kind == 'reset':
            st['result'] = record(sid, 'cancelled')
        elif kind == 'fin':
            st['result'] = handle_fin(sid, index, st['items'], routes, pipelines)

    streams = []
    for sid in sorted(states):
        st = states[sid]
        if st['result'] is None:
            st['result'] = record(sid, 'incomplete')
        streams.append(st['result'])
    origins = {label: bytes(pipe).hex() for label, pipe in pipelines.items()}
    return {'streams': streams, 'origins': origins}


def main():
    scenario = json.load(sys.stdin)
    json.dump(bridge(scenario), sys.stdout, ensure_ascii=True)
    sys.stdout.write('\n')


if __name__ == '__main__':
    main()
